export const TIME_ZONE_COUNTRIES = new Map();
for (const [country, packed] of Object.entries(PACKED)) {
  for (const group of packed.split(' ')) {
    const slash = group.indexOf('/');
    if (slash < 0) { TIME_ZONE_COUNTRIES.set(group, country); continue; }
    const prefix = group.slice(0, slash + 1);
    for (const name of group.slice(slash + 1).split(',')) TIME_ZONE_COUNTRIES.set(prefix + name, country);
  }
}

export const countryForTimeZone = zone => (typeof zone === 'string' && TIME_ZONE_COUNTRIES.get(zone)) || '';
